import{z as E,x as d,o as r,c as p,q as n,j as l,D as t,d as A,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"NAPT 与端口","description":"","frontmatter":{"title":"NAPT 与端口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/napt.md","filePath":"cs/napt.md","lastUpdated":1791063341000}'),P={name:"cs/napt.md"};function B(T,a,N,m,h,c){const s=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="napt-与端口" tabindex="-1">NAPT 与端口 <a class="header-anchor" href="#napt-与端口" aria-label="Permalink to &quot;NAPT 与端口&quot;">​</a></h1><div class="epigraph"><p>只改 IP 不够：多台主机共用一个公网地址时，必须用传输层端口把会话从地址对里拆开。</p><footer>—— 据 RFC 3022 对传统 NAT；Kurose and Ross 对端口映射的整理</footer></div><p><a href="/cs/dhcp-nat">上一课</a>同时给出租约与「私网复用公网地址」。本课不重做 DHCP 状态机。缺口是 NAT 的细档：一对一改地址（基本 NAT）扛不住多对一；必须做 <strong>NAPT</strong>：改写 IP 与端口，用表记住内部四元组与外部的对应。本课不把 IPv6 当已部署完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dhcp-nat">DHCP 与 NAT</a> 留下「改写 IP 与端口」。若只换源 IP，两台主机连同一服务器同一服务时，回来的包无法区分。NAPT 把源端口也纳入键：外出建立映射，进入时按目的端口反查。无连接的 UDP 也要计时；ICMP 查询用 identifier。缺口是<strong>会话表</strong>，不是新的私网前缀。</p><p><span class="marginnote">直觉类比：NAPT 像公司前台代收快递——全体员工对外都用公司地址（唯一公网 IP），前台再按「工位号」（端口）把件分给个人；没登记过的陌生来件一律拒收。内部两个人寄给同一收件人也不冲突，因为前台给他们编了不同的寄件号。</span></p><p><span class="marginnote">数字实例：主机 A（192.168.1.10:5000）与主机 B（192.168.1.11:5000）都访问同一服务器。只换 IP 的话两个会话无法区分；NAPT 分别改写成 203.0.113.7:40001 和 :40002。服务器回包按目的端口反查：40001 送 A，40002 送 B，两不误。</span></p><p><span class="marginnote">传输层尚未开课，但端口字段已在 UDP/TCP 头里。本课只把端口当成 NAT 的解复用键；套接字语义后课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外出：若无映射则分配外部端口，改源 IP/端口，重算校验。进入：查表改回内部目的，无表则丢（默认不接受未请求的入连接）。超时回收。端口受限与对称 NAT 改变「对谁可见」的松紧，影响后课穿越，本课只承认分档存在。</p>',10)),(r(),l(i,null,{default:t(()=>[o(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INH%5B%22%E5%86%85%E9%83%A8%E4%B8%BB%E6%9C%BA%3A%20%E7%A7%81%E7%BD%91%20IP%22%5D%20--%3E%20TAB%5B%22NAPT%20%E4%BC%9A%E8%AF%9D%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20WAN%5B%22%E5%85%AC%E7%BD%91%20IP%20%E5%8A%A0%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20WAN%20--%3E%20REV%5B%22%E5%85%A5%E5%8C%85%E6%8C%89%E7%AB%AF%E5%8F%A3%E5%8F%8D%E6%9F%A5%22%5D%0A%20%20REV%20--%3E%20INH%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[A("NAPT 把"),e("a",{href:"/cs/layering-e2e"},"端到端"),A("的地址透明性撕开：中间盒持有连接状态，与路由器「只转发」不同。IP 分片、ICMP 错误必须能关联到表项，否则映射断裂。对后课 TCP 握手：SYN 外出建表；对端看到的是公网四元组。安全上它不是防火墙规格，只是顺带丢未映射入包。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为「家里路由器有 NAT 所以很安全」。丢弃未请求的入包只是 NAPT 的副作用，不是安全规格——它不检查内容、不做策略；一旦内网主动发起连接开洞（或被打了端口映射），它不提供任何额外保护。")],-1)),(r(),l(i,null,{default:t(()=>[o(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E4%B8%BB%E6%9C%BA%20A%20192.168.1.10%3A5000%22%5D%20--%3E%20T%5B%22NAPT%20%E4%BC%9A%E8%AF%9D%E8%A1%A8%22%5D%0A%20%20B%5B%22%E4%B8%BB%E6%9C%BA%20B%20192.168.1.11%3A5000%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20WA%5B%22%E5%85%AC%E7%BD%91%20203.0.113.7%3A40001%22%5D%0A%20%20T%20--%3E%20WB%5B%22%E5%85%AC%E7%BD%91%20203.0.113.7%3A40002%22%5D%0A%20%20WA%20--%3E%20S%5B%22%E5%90%8C%E4%B8%80%E6%9C%8D%E5%8A%A1%E5%99%A8%3A443%22%5D%0A%20%20WB%20--%3E%20S%0A%20%20S%20--%3E%20RV%5B%22%E5%9B%9E%E5%8C%85%E6%8C%89%E7%9B%AE%E7%9A%84%E7%AB%AF%E5%8F%A3%E5%8F%8D%E6%9F%A5%E5%88%86%E5%8F%91%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 NAT 穿越协议写成教程，不引入运营商级 NAT 的日志法规。IPv6 对照下一课：地址够用时仍可能有防火墙状态，但不靠 NAPT 省地址。</p><p>后课默认：IPv4 边缘常见「多主机、一公网、靠端口表」。128 位地址如何改写邻居发现，下一课起对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NAPT 用端口把多台私网主机复用到少量公网 IP。</li><li>入方向默认只接受表上有的会话。</li><li>IPv6 是另一条路，下一课对照。</li><li>出处：RFC 3022；Kurose and Ross。</li></ul>',5))])}const f=E(P,[["render",B]]);export{C as __pageData,f as default};
